import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line = br.readLine();if (line == null) return;long n = Long.parseLong(line.trim());long result;if (n % 2 == 0) {result = n / 2;} else {result = -(n + 1) / 2;}System.out.println(result);}}